1. SELECT REPLACE(technician_name, ' ', '') AS technician_name_no_spaces FROM technicians WHERE specialty = 'relay' ORDER BY technician_name;
2. SELECT DISTINCT REPLACE(t.technician_name, ' ', '') AS technician_name_no_spaces FROM technicians t JOIN work_orders wo ON t.technician_id = wo.assigned_technician_id WHERE t.specialty = 'relay' AND wo.fault_code = 'RELAY' ORDER BY t.technician_name;
3. SELECT REPLACE(t.technician_name, ' ', '') AS technician_name_no_spaces FROM technicians t JOIN maintenance_logs ml ON t.technician_id = ml.technician_id JOIN work_orders wo ON ml.work_order_id = wo.work_order_id WHERE t.specialty = 'relay' AND wo.fault_code = 'RELAY' ORDER BY t.technician_name;
